export const geometryDefinition=base({templateId:'question-template:y13:differentiation:connected-rates:geometry',assessmentObjective:'ao1',microSkillId:skill('chain-rule-connection'),responseType:'choice',responseLabel:'Rate',errorCategories:['substitute-first','rate-calculation'],diagnosticRules:{'substitute-first':{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('dependency-chain'),studentMessage:'Build t → r → A before using the numbers.'},'rate-calculation':{kind:'execution',supportNeed:'ao1',supportMicroSkillId:skill('chain-rule-connection'),studentMessage:'Use dA/dt=(dA/dr)(dr/dt).'}},defaultDiagnostic:{kind:'execution',supportNeed:'ao1',supportMicroSkillId:skill('chain-rule-connection')},parameterGenerator:()=>({}),promptRenderer:()=> 'A circular ripple has radius 4 cm and dr/dt=0.5 cm s⁻¹. Find dA/dt.',responseOptionsRenderer:()=>[choice('a','4π cm² s⁻¹'),choice('b','8π cm² s⁻¹'),choice('c','2π cm s⁻¹')],answerChecker:r=>r==='a'?ok():bad('rate-calculation','dA/dt=2πr·dr/dt=2π(4)(0.5)=4π.'),workedSolutionGenerator:()=>[step('1','Dependency','t → r → A','Area depends on radius, which depends on time.'),step('2','Connect','dA/dt=(dA/dr)(dr/dt)=2πr·dr/dt','Use the chain rule.'),step('3','Substitute','2π(4)(0.5)=4π cm² s⁻¹','Attach area-per-time units.') ]});
